create extension if not exists "pgcrypto"; create table profiles(id uuid primary key references auth.users(id), username text unique not null, full_name text not null, country text, timezone text default 'UTC', currency text default 'USD', created_at timestamptz default now()); create table projects(id uuid primary key default gen_random_uuid(), client_id uuid references profiles(id), title text not null, description text not null, status text default 'draft', budget numeric, currency text default 'USD', created_at timestamptz default now()); create table services(id uuid primary key default gen_random_uuid(), owner_id uuid references profiles(id), title text not null, description text not null, status text default 'draft', created_at timestamptz default now()); alter table profiles enable row level security; alter table projects enable row level security; alter table services enable row level security;
